pub fn unique_strings(items: Vec<String>) -> Vec<String> {
    {
        let result = items.clone().iter().cloned().fold(
            Rc::new(UniqueAccum {
                seen: <HashMap<_, _>>::new(),
                result: vec![],
            }),
            |acc: _, item: String| {
                if emit_map_has(acc.seen.clone(), item.clone()) {
                    acc.clone()
                } else {
                    Rc::new(UniqueAccum {
                        seen: v2_rt::map_insert(acc.seen.clone(), item.clone(), true),
                        result: v2_rt::list_push(acc.result.clone(), item.clone()),
                    })
                }
            },
        );
        result.result.clone()
    }
}

